questionvariables.text:
N: 50+rand(50);
nb: 8+rand(5);
r: rand([3/5, 7/10, 4/5]);
w: makelist(r^(i-1)+1/10, i, 1, nb);
S: lsum(z, z, w);
cnt0: makelist(floor(N*w[i]/S), i, 1, nb);
cnt: cons(cnt0[1] + N - lsum(z, z, cnt0), rest(cnt0));
xc: makelist(6*(i-1)+3, i, 1, nb);
maxc: lmax(cnt);
dots: apply(append, makelist(makelist(xc[i], k, 1, cnt[i]), i, 1, nb));
tm: sum(cnt[i]*xc[i], i, 1, nb)/N;
med: if oddp(N) then dots[(N+1)/2] else (dots[N/2]+dots[N/2+1])/2;
tmd: float(round(10*tm)/10);
medd: float(round(10*med)/10);
nl: length(sublist(dots, lambda([z], z < med)));
nr: length(sublist(dots, lambda([z], z > med)));
ne: N - nl - nr;
ta1: [tm, -1];
ta2: [med, -2];

feedbackvariables.text:
m: float(ans1[1]);
d: float(ans2[1]);
ok10m: is(abs(m-tm) <= 0.1*abs(tm));
ok20m: is(abs(m-tm) <= 0.2*abs(tm));
ok10d: is(abs(d-med) <= 0.1*abs(med));
ok20d: is(abs(d-med) <= 0.2*abs(med));
pos: is(m > d);
